                 [0, 0, 0, 0, 0, 0, 0, 0, 0]]

boundary, interior = identify_boundary_interior(input_grid_ex3)
print(f"Number of boundary pixels: {len(boundary)}")
print(f"Number of interior pixels: {len(interior)}")
